 1	import { appendFileSync, mkdirSync } from "node:fs";
 2	import { dirname } from "node:path";
 3	import type { RetrievedExperience } from "./types.ts";
 4	
 5	/**
 6	 * Request-level observability helpers (O spec R3).
 7	 *
 8	 * Local/remote attribution rule: the ids/kinds logged at phase=retrieval are
 9	 * the LOCAL experience-store content injected into this request; the response
10	 * content logged at phase=done is produced by the REMOTE LLM. The request id
11	 * ties log lines, the session JSONL (header metadata.requestId), the
12	 * request_traces row, and the x-request-id response header together.
13	 */
14	
15	/** "TYPE:role" kind strings for retrieved experiences, e.g. "ABILITY:Method". */
16	export function kindsOf(retrieved: RetrievedExperience[]): string[] {
17		return retrieved.map((r) => {
18			const role = (r.experience.payload as Record<string, unknown>).role;
19			return `${r.experience.type}:${typeof role === "string" && role ? role : "null"}`;
20		});
21	}
22	
23	/** Human-readable Chinese labels for kind strings (logs/stats page). */
24	const KIND_LABELS: Record<string, string> = {
25		"ABILITY:Method": "方法",
26		"ABILITY:Guard": "护栏",
27		"EVIDENCE:null": "证据",
28		"EVIDENCE:Workflow": "工作流",
29		"SKILL:null": "技能",
30		"SOP:null": "SOP",
31	};
32	
33	/** Kind strings → compact Chinese summary, e.g. "方法×7,证据×1". */
34	export function summarizeKinds(kinds: string[]): string {
35		const counts = new Map<string, number>();
36		for (const kind of kinds) counts.set(kind, (counts.get(kind) ?? 0) + 1);
37		return [...counts.entries()].map(([kind, cnt]) => `${KIND_LABELS[kind] ?? kind}×${cnt}`).join(",");
38	}
39	
40	/** Titles of retrieved experiences for the trace log: first `max` + overflow count. */
41	export function titlesOf(retrieved: RetrievedExperience[], max = 3): string {
42		const titles = retrieved.slice(0, max).map((r) => r.experience.title);
43		const rest = retrieved.length - titles.length;
44		return rest > 0 ? `${titles.join("; ")} 等${retrieved.length}条` : titles.join("; ");
45	}
46	
47	/**
48	 * Optional file sink for trace logs (web monitor /api/logs). Set once at
49	 * server startup; stdout logging continues regardless (container discipline).
50	 */
51	let logFilePath: string | null = null;
52	
53	export function setLogFile(path: string): void {
54		logFilePath = path;
55	}
56	
57	/** One structured trace log line on stdout (container logs stay parseable). */
58	export function logTrace(requestId: string, phase: string, fields: Record<string, unknown> = {}): void {
59		const parts = Object.entries(fields)
60			.map(([k, v]) => `${k}=${typeof v === "string" && v.includes(" ") ? JSON.stringify(v) : String(v)}`)
61			.join(" ");
62		const line = `[agent-server] req=${requestId} phase=${phase}${parts ? ` ${parts}` : ""}`;
63		console.log(line);
64		if (logFilePath) {
65			try {
66				mkdirSync(dirname(logFilePath), { recursive: true });
67				appendFileSync(logFilePath, `${new Date().toISOString()} ${line}\n`);
68			} catch {
69				// Logging must never break a request.
70			}
71		}
72	}

