 26	export interface CreateServerOptions {
 27		store?: ExperienceStore;
 28		gatewayUrl?: string;
 29		sessionDir?: string;
 30		/** Server-level injection default; env AGENT_SERVER_INJECTION=off disables. Per-request `injection` overrides. */
 31		injection?: boolean;
 32		/** Web monitor switch; env AGENT_SERVER_WEB=off disables /dashboard, /api/logs, /api/status/chain. Default on. */
 33		web?: boolean;
 34		/** Trace-log file path for the file sink + /api/logs; env AGENT_SERVER_LOG_PATH. Default ./var/log/agent-server.log. */
 35		logPath?: string;
 36	}
