 38	/**
 39	 * Fastify server exposing `POST /api/stream` (SPEC §4.1). Dependencies are
 40	 * injectable for tests; by default they come from env vars
 41	 * (EXPERIENCE_STORE_PATH, GATEWAY_URL, AGENT_SERVER_SESSION_DIR).
 42	 */
 43	export function createServer(opts: CreateServerOptions = {}): FastifyInstance {
 44		const fastify = Fastify({ logger: false });
 45		const gatewayUrl = opts.gatewayUrl ?? process.env.GATEWAY_URL ?? "http://127.0.0.1:8787";
 46		const sessionDir = opts.sessionDir ?? process.env.AGENT_SERVER_SESSION_DIR ?? "./var/sessions";
 47		const injectionDefault = opts.injection ?? process.env.AGENT_SERVER_INJECTION !== "off";
 48		const webEnabled = opts.web ?? process.env.AGENT_SERVER_WEB !== "off";
 49		const logPath = opts.logPath ?? process.env.AGENT_SERVER_LOG_PATH ?? "./var/log/agent-server.log";
 50		setLogFile(logPath);
 51		logTrace("-", "startup", {
 52			web: webEnabled ? "on" : "off",
 53			injection: injectionDefault ? "on" : "off",
 54			log: logPath,
 55		});
 56	
 57		let store = opts.store;
 58		if (!store) {
 59			const storePath = process.env.EXPERIENCE_STORE_PATH ?? "./var/experience.db";
 60			mkdirSync(dirname(storePath), { recursive: true });
 61			// M10 (adversarial review 2026-08-09): AGENT_SERVER_STORE_SNAPSHOT pins
 62			// experience reads to a frozen copy for the server's lifetime — batch
 63			// runs are immune to mid-run library writes (manual evolution, dormant
 64			// promotion, TTL cleanup) changing the retrieval behavior. The runner
 65			// must create the snapshot before starting the instance
 66			// (eval/snapshot_store.py); the live db stays the single writer.
 67			const snapshotPath = process.env.AGENT_SERVER_STORE_SNAPSHOT;
 68			store = new ExperienceStore(storePath, snapshotPath ? { snapshotPath } : {});
 69			// better-sqlite3 is synchronous internally, so the schema exists before
 70			// any request is served even though initSchema is typed async.
 71			void store.initSchema();
 72		}
 73	
 74		// -- offline evolution status (SPEC B3: expose last checkpoint to monitoring) --
 75		fastify.get("/api/evolution/status", async (_request, reply) => {
 76			const latest = await store.getLatestCheckpoint("evolution");
 77			if (!latest) {
 78				return reply.code(404).send({ status: "never_run" });
 79			}
 80			let snapshot: unknown;
 81			try {
 82				snapshot = JSON.parse(latest.snapshot);
 83			} catch {
 84				snapshot = latest.snapshot;
 85			}
 86			return reply.send({
 87				status: "found",
 88				id: latest.id,
 89				epoch: new Date(latest.epoch).toISOString(),
 90				metric: latest.metric,
 91				snapshot,
 92			});
 93		});
 94	
 95		// -- O spec R2: hit-rate stats API + page -------------------------------
 96		fastify.get("/api/stats/hit-rate", async (request, reply) => {
 97			const query = request.query as { window_hours?: string };
 98			const windowHours = Number(query.window_hours) > 0 ? Number(query.window_hours) : 24;
 99			return reply.send(await store.getHitRateStats(windowHours));
100		});
101	
102		fastify.get("/stats", async (_request, reply) => {
103			return reply.header("content-type", "text/html; charset=utf-8").send(STATS_PAGE_HTML);
104		});
105	
106		// -- Web monitor (2026-08-05): dashboard + chain status + log access. -----
107		// Gated by the web switch (AGENT_SERVER_WEB=off); data APIs above stay open.
108		if (webEnabled) {
109			fastify.get("/dashboard", async (_request, reply) => {
110				return reply.header("content-type", "text/html; charset=utf-8").send(DASHBOARD_PAGE_HTML);
111			});
112	
113			fastify.get("/api/status/chain", async (_request, reply) => {
114				const gateway = await probeService(`${gatewayUrl}/v1/models`, gatewayAuthHeaders());
115				const omlxUrl = process.env.OMLX_URL ?? "http://127.0.0.1:8000";
116				const omlx = await probeService(`${omlxUrl}/v1/models`);
117				const latest = await store.getLatestCheckpoint("evolution");
118				return reply.send({
119					self: { ok: true, uptimeS: Math.round(process.uptime()), web: true, injection: injectionDefault },
120					gateway,
121					omlx,
122					evolution: latest
123						? { id: latest.id, epoch: new Date(latest.epoch).toISOString(), metric: latest.metric }
124						: null,
125				});
126			});
127	
128			fastify.get("/api/logs", async (request, reply) => {
129				const query = request.query as { lines?: string };
130				const limit = Math.min(Math.max(Number(query.lines) || 200, 1), 1000);
131				if (!existsSync(logPath)) return reply.send({ lines: [] });
132				const content = await readFile(logPath, "utf-8");
133				const lines = content
134					.trimEnd()
135					.split("\n")
136					.filter((l) => l.length > 0);
137				return reply.send({ lines: lines.slice(-limit) });
138			});
139		}
