144			// (same two-phase upsert as /v1) — requestId is a randomUUID so it never
145			// collides across days/instances, and the x-request-id header, session
146			// header metadata, and trace row stay consistent (O spec R4 contract).
147			const requestId = randomUUID();
148			reply.header("x-request-id", requestId);
149			const taskId = typeof body.taskId === "string" && body.taskId.trim() ? body.taskId : undefined;
150			const domain = typeof body.domain === "string" && body.domain.trim() ? body.domain : undefined;
151			const sessionPath = join(sessionDir, `${Date.now()}-${randomUUID()}.jsonl`);
152			try {
153				const stream = await handleStream(body, {
154					store,
155					gatewayUrl,
156					sessionPath,
157					injection: injectionDefault,
158					requestId,
159					...(taskId !== undefined ? { taskId } : {}),
160					...(domain !== undefined ? { domain } : {}),
161				});
162				reply.header("content-type", "text/event-stream");
163				return reply.send(Readable.fromWeb(stream as unknown as NodeReadableStream<Uint8Array>));
164			} catch (err) {
